#!/usr/bin/env python3
"""Per-business kits for Afterstreet: for each OSM business tag on the Springfield map, the sign, rooms, fixtures, exterior items, what it needs to operate and what a survivor finds.
Writes assets/shaped/businesses.js (window.BUSINESSES). Fixture rows are [thing, where, count, extras] like interiors.js roomFixtures; `thing` is `pack.piece` (interiors, foodservice, autotrade, services, shopfit) and is checked against the packs.
Run: python3 assets/shaped/src/biz_kits.py"""
import json, subprocess, os
H = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(os.path.dirname(H), 'businesses.js')
def names():
    js = "global.window={};for(const n of ['interiors','foodservice','autotrade','services','shopfit'])require('%s/'+n+'.js');const o={};for(const n of ['interiors','foodservice','autotrade','services','shopfit'])for(const g of Object.values(window.SHAPED[n].models))for(const k of Object.keys(g))o[n+'.'+k]=1;console.log(JSON.stringify(o))" % os.path.dirname(H)
    return json.loads(subprocess.check_output(['node', '-e', js]))
OK = names()
def F(*rows): return [list(r) for r in rows]
SH = lambda n: 'shopfit.' + n; FS = lambda n: 'foodservice.' + n; AT = lambda n: 'autotrade.' + n; SV = lambda n: 'services.' + n; IN = lambda n: 'interiors.' + n
door = [SH('glass_door'), 'door', 1, {}]
def K(tag, sign, staff, rooms, fixtures, exterior, needs, loot, floor='floor_linoleum'):
    return {'tag': tag, 'sign': sign, 'staff': staff, 'rooms': rooms, 'fixtures': fixtures, 'exterior': exterior, 'needs': needs, 'loot': loot, 'floor': floor}
B = {}
def A(*a): k = K(*a); B[k['tag']] = k
N = lambda **k: k
